import pandas as pd
def clean(df):
    df = df.copy()
    # remove exact duplicate rows (affects order count)
    df = df.drop_duplicates()
    # normalize Category label variants: case differences and typo Furnture
    if 'Category' in df.columns:
        mapping = {
            'electronics': 'Electronics',
            'accessories': 'Accessories',
            'furniture': 'Furniture',
            'office supplies': 'Office Supplies',
            'furnture': 'Furniture'
        }
        def norm_cat(x):
            if pd.isna(x):
                return x
            s = str(x).strip()
            low = s.lower()
            return mapping.get(low, s)
        df['Category'] = df['Category'].apply(norm_cat)
    # ensure numeric columns are numeric (if stored as text)
    for col in ['Order_ID', 'Quantity', 'Price', 'Revenue']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')
    # parse Date to validate format, keep rows (not needed for category count)
    if 'Date' in df.columns:
        df['Date'] = pd.to_datetime(df['Date'], errors='coerce')
    return df

def answer(df):
    # count orders per Category, drop missing group keys
    d = df.dropna(subset=['Category'])
    counts = d.groupby('Category').size()
    return {str(k): int(v) for k, v in counts.items()}
